/**
 * The post-fit unit-circle node move: libena's move_nodes_to_unit_circle and
 * ena.moveNodesToUnitCircle(model, opts).
 *
 * Fixture test/fixtures/unit-circle-rs.json holds R reference values on
 * RS.data from the R implementation libena replaced
 * (move_nodes_to_unit_circle*() in rENA's R/move_nodes.R); generated by
 * test/fixtures/unit-circle-rs.R. Its ordered centroids use the directed
 * weighting (the R implementation read only the i < j connections).
 */
import fs   from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import loadENA from '../src/index.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const EXTDATA   = path.resolve(__dirname, '../../inst/extdata');
const FIXTURE   = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures/unit-circle-rs.json'), 'utf8'));

function parseCSVRow(line) {
    const result = [];
    let current  = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (ch === '\r') continue;
        if (ch === '"') {
            if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
            else inQuotes = !inQuotes;
        } else if (ch === ',' && !inQuotes) {
            result.push(current);
            current = '';
        } else {
            current += ch;
        }
    }
    result.push(current);
    return result;
}

function parseCSV(text) {
    const lines   = text.split('\n').filter(l => l.trim().replace(/\r/g, '') !== '');
    const headers = parseCSVRow(lines[0]);
    return lines.slice(1).map(line => {
        const values = parseCSVRow(line);
        return Object.fromEntries(headers.map((h, i) => [h, values[i] ?? '']));
    });
}

const CODES = ['Data', 'Technical Constraints', 'Performance Parameters',
               'Client and Consultant Requests', 'Design Reasoning', 'Collaboration'];
const BASE  = { codes: CODES, units: ['Condition', 'UserName'],
                conversations: ['Condition', 'GroupName'], window: 4, dims: 4 };

const flat = (m) => Float64Array.from(m.flat());

function expectClose(actual, expected, tol = 1e-10) {
    expect(actual.length).toBe(expected.length);
    let max = 0;
    for (let i = 0; i < actual.length; i++) {
        const scale = Math.max(1, Math.abs(expected[i]));
        max = Math.max(max, Math.abs(actual[i] - expected[i]) / scale);
    }
    expect(max).toBeLessThan(tol);
}

// Centroids computed here in JS: each unit's line weights split between the
// codes they connect (unordered: half to each; ordered: in full to both, a
// self-connection once), rows normalised to sum to 1, times the nodes.
function centroidsOf(model, nodes) {
    const n = model.rotation.codes.length, d = model.dims, ordered = model.nConnections === n * n;
    const out = new Float64Array(model.nUnits * d);
    for (let u = 0; u < model.nUnits; u++) {
        const w = new Float64Array(n);
        let k = 0;
        if (ordered) {
            for (let j = 0; j < n; j++)
                for (let i = 0; i < n; i++, k++) {
                    const v = model.lineWeights[u * model.nConnections + k];
                    w[i] += v;
                    if (i !== j) w[j] += v;
                }
        } else {
            for (let j = 1; j < n; j++)
                for (let i = 0; i < j; i++, k++) {
                    const v = model.lineWeights[u * model.nConnections + k];
                    w[i] += v / 2;
                    w[j] += v / 2;
                }
        }
        const s = w.reduce((a, b) => a + Math.abs(b), 0);
        for (let c = 0; c < n; c++)
            for (let dd = 0; dd < d; dd++)
                out[u * d + dd] += (s > 0 ? w[c] / s : 0) * nodes[c * d + dd];
    }
    return out;
}

let ena, rows;
beforeAll(async () => {
    ena  = await loadENA();
    rows = parseCSV(fs.readFileSync(path.join(EXTDATA, 'rs.data.csv'), 'utf8'));
});

describe('libena move_nodes_to_unit_circle matches R', () => {
    for (const c of FIXTURE.cases) {
        test(`${c.model}, ${c.mode}, dims ${c.dims}`, () => {
            const m  = FIXTURE.models[c.model];
            const lw = flat(m.line_weights), nodes = flat(m.nodes);
            const r  = ena.qe.move_nodes_to_unit_circle(
                lw, m.line_weights.length, m.line_weights[0].length,
                nodes, m.nodes.length, m.nodes[0].length,
                c.dims[0], c.dims[1], c.mode, m.directed);
            expect([r.nodes.rows, r.nodes.cols]).toEqual([m.nodes.length, m.nodes[0].length]);
            expectClose(r.nodes.data, flat(c.nodes));
            expectClose(r.centroids.data, flat(c.centroids));
        });
    }
});

describe('ena.moveNodesToUnitCircle', () => {
    for (const ordered of [false, true]) {
        for (const mode of ['equal', 'radial']) {
            test(`${ordered ? 'ordered' : 'unordered'} model, ${mode}`, () => {
                const fit = ena.fit(rows, { ...BASE, ordered });
                const nodesBefore = Float64Array.from(fit.rotation.nodes);
                const centroidsBefore = Float64Array.from(fit.model.centroids);
                const moved = ena.moveNodesToUnitCircle(fit, { dims: [2, 1], mode });

                // the fitted model is unchanged; the copy keeps its class and points
                expect(fit.rotation.nodes).toEqual(nodesBefore);
                expect(fit.model.centroids).toEqual(centroidsBefore);
                expect(moved.constructor).toBe(fit.constructor);
                expect(moved.points).toBe(fit.points);
                expect(moved.model.unitLabels).toBe(fit.model.unitLabels);
                expect(moved.centroid(fit.model.unitLabels[0])).toHaveLength(fit.dims);

                // same as the low-level call
                const n = fit.rotation.codes.length, d = fit.dims;
                const r = ena.qe.move_nodes_to_unit_circle(
                    fit.lineWeights, fit.nUnits, fit.nConnections,
                    fit.rotation.nodes, n, d, 2, 1, mode, ordered);
                expect(moved.rotation.nodes).toEqual(new Float64Array(r.nodes.data));
                expect(moved.model.centroids).toEqual(new Float64Array(r.centroids.data));

                // on the circle in dims (2, 1); dims 0 and 3 unchanged
                const radius = (nodes, c) => Math.hypot(nodes[c * d + 2], nodes[c * d + 1]);
                const rMax = Math.max(...Array.from({ length: n }, (_, c) => radius(nodesBefore, c)));
                for (let c = 0; c < n; c++) {
                    expect(radius(moved.rotation.nodes, c)).toBeCloseTo(rMax, 12);
                    expect(moved.rotation.nodes[c * d]).toBe(nodesBefore[c * d]);
                    expect(moved.rotation.nodes[c * d + 3]).toBe(nodesBefore[c * d + 3]);
                }

                // centroids: the fit's weighting times the moved nodes
                expectClose(moved.model.centroids, centroidsOf(fit, moved.rotation.nodes));
                // ... which with the fitted nodes gives the fitted centroids
                // (ordered models translate their nodes after the fit, so
                // unordered only)
                if (!ordered) expectClose(fit.model.centroids, centroidsOf(fit, nodesBefore));
            });
        }
    }

    test('defaults: equal spacing in dims 0 and 1', () => {
        const fit = ena.fit(rows, BASE);
        const moved = ena.moveNodesToUnitCircle(fit);
        const n = fit.rotation.codes.length, d = fit.dims;
        const angles = Array.from({ length: n }, (_, c) =>
            Math.atan2(moved.rotation.nodes[c * d + 1], moved.rotation.nodes[c * d]))
            .map(a => (a + 2 * Math.PI) % (2 * Math.PI)).sort((a, b) => a - b);
        for (let i = 1; i < n; i++) expect(angles[i] - angles[i - 1]).toBeCloseTo(2 * Math.PI / n, 12);
    });

    test('bad arguments throw with the reason', () => {
        const fit = ena.fit(rows, BASE);
        expect(() => ena.moveNodesToUnitCircle(fit, { mode: 'spiral' })).toThrow(/mode must be/);
        expect(() => ena.moveNodesToUnitCircle(fit, { dims: [0, 4] })).toThrow(/dims must be/);
        expect(() => ena.moveNodesToUnitCircle(fit, { dims: [1, 1] })).toThrow(/must differ/);
        expect(() => ena.moveNodesToUnitCircle({}, {})).toThrow(/fitted model/);
    });
});
